def _try_repr_or_str(obj):
    try:
        return repr(obj)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException:
        # If we can't get a repr/str, return a placeholder.
        # We must avoid accessing obj attributes that might also fail.
        try:
            name = type(obj).__name__
        except Exception:
            name = "object"
        return '{}("...")'.format(name)


def _format_repr_exception(exc: BaseException, obj: Any) -> str:
    try:
        exc_info = _try_repr_or_str(exc)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc2:
        exc_info = "unpresentable exception ({})".format(_try_repr_or_str(exc2))

    try:
        class_name = obj.__class__.__name__
    except Exception:
        class_name = "object"

    try:
        obj_id = id(obj)
    except Exception:
        obj_id = 0

    return "<[{} raised in repr()] {} object at 0x{:x}>".format(
        exc_info, class_name, obj_id
    )

class SafeRepr(reprlib.Repr):
    def __init__(self, maxsize=64, use_reprlib=True):
        self.maxsize = maxsize
        self.use_reprlib = use_reprlib
        if use_reprlib:
            super().__init__()

    def repr(self, x: Any) -> str:
        try:
            s = super().repr(x)
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException as exc:
            s = _format_repr_exception(exc, x)
        return _ellipsize(s, self.maxsize)

    def repr_instance(self, x: Any, level: int) -> str:
        try:
            s = repr(x)
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException as exc:
            return _format_repr_exception(exc, x)
        return _ellipsize(s, self.maxsize)
