    "You have 'APP_DIRS': True in your TEMPLATES but also specify 'loaders' "
    "in OPTIONS. Either remove APP_DIRS or remove the 'loaders' option.",
    id="templates.E001",
)
E002 = Error(
    "'string_if_invalid' in TEMPLATES OPTIONS must be a string but got: {} ({}).",
    id="templates.E002",
)
E003 = Error(
    "{} is used for multiple template tag modules: {}",
    id="templates.E003",
)


@register(Tags.templates)
def check_setting_app_dirs_loaders(app_configs, **kwargs):
    return (
        [E001]
        if any(
            conf.get("APP_DIRS") and "loaders" in conf.get("OPTIONS", {})
            for conf in settings.TEMPLATES
        )
        else []
    )


@register(Tags.templates)
def check_string_if_invalid_is_string(app_configs, **kwargs):
    errors = []
    for conf in settings.TEMPLATES:
        string_if_invalid = conf.get("OPTIONS", {}).get("string_if_invalid", "")
        if not isinstance(string_if_invalid, str):
            error = copy.copy(E002)
            error.msg = error.msg.format(
                string_if_invalid, type(string_if_invalid).__name__
            )
            errors.append(error)
    return errors


@register(Tags.templates)
def check_for_template_tags_with_the_same_name(app_configs, **kwargs):
    errors = []
    libraries = defaultdict(list)

    for conf in settings.TEMPLATES:
        custom_libraries = conf.get("OPTIONS", {}).get("libraries", {})
        for module_name, module_path in custom_libraries.items():
            libraries[module_name].append(module_path)

    for module_name, module_path in get_template_tag_modules():
        # Only add to libraries if it's not already present from custom_libraries
        # This prevents double-counting if a custom library points to an existing one
        if module_name not in libraries:
            libraries[module_name].append(module_path)

    for library_name, items in libraries.items():
        # Check for duplicates within the list itself (e.g., same path added twice)
        # or if multiple different paths map to the same name
        if len(items) > 1:
            # If all items are the same, it's likely a configuration error where
            # the same key was defined multiple times in OPTIONS['libraries']
            # which Python dicts don't allow. However, if we have distinct paths
            # for the same name, that's the real conflict.
            # The original issue implies that adding a library to OPTIONS['libraries']
            # might cause it to be flagged against itself or other instances.
            # Let's look at the actual items.
            unique_items = set(items)
            if len(unique_items) > 1:
                errors.append(
                    Error(
                        E003.msg.format(
                            repr(library_name),
                            ", ".join(repr(item) for item in items),
                        ),
                        id=E003.id,
                    )
                )
            elif len(items) > 1:
                # This case handles if somehow the same path is added multiple times
                # due to logic error, though dict keys prevent duplicate keys.
                # It might happen if `get_template_tag_modules` returns duplicates?
                # Unlikely. But let's just report it as an error if there are duplicates.
                errors.append(
                    Error(
                        E003.msg.format(
                            repr(library_name),
                            ", ".join(repr(item) for item in items),
                        ),
                        id=E003.id,
                    )
                )

    return errors
